function minPairSum(nums) {
  const sorted = [...nums].sort((a, b) => a - b);
  let left = 0;
  let right = sorted.length - 1;
  let best = 0;

  while (left < right) {
    const pairSum = sorted[left] + sorted[right];
    best = Math.max(best, pairSum);
    left++;
    right--;
  }
  return best;
}

