function minPairSum(nums) {
  const n = nums.length;
  const taken = new Array(n).fill(false);
  let best = Infinity;
  const search = (worst) => {
    const first = taken.indexOf(false);
    if (first === -1) {
      best = Math.min(best, worst);
      return;
    }
    taken[first] = true;
    for (let k = first + 1; k < n; k++) {
      if (taken[k]) continue;
      taken[k] = true;
      search(Math.max(worst, nums[first] + nums[k]));
      taken[k] = false;
    }
    taken[first] = false;
  };
  search(0);
  return best;
}

